package com.hbm.client.oilplant;
import com.hbm.block.oilplant.*;import com.hbm.hazard.HbmHazards;import mezz.jei.api.*;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.ingredients.subtypes.*;import mezz.jei.api.registration.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.ItemStack;
@JeiPlugin public final class OilBotanyJeiPlugin implements IModPlugin {
 @Override public ResourceLocation getPluginUid(){return ResourceLocation.parse("hbm:oil_botany_jei");}@Override public void registerExtraIngredients(IExtraIngredientRegistration e){for(var tab:java.util.List.of("block","parts"))e.addExtraIngredients(VanillaTypes.ITEM_STACK,OilBotanyContent.creativeStacks(tab));}@Override public void registerItemSubtypes(ISubtypeRegistration e){var interpreter=new ISubtypeInterpreter<ItemStack>(){@Override public Object getSubtypeData(ItemStack s,UidContext context){return s.getOrDefault(HbmHazards.LEGACY_METADATA.get(),0);}@Override public String getLegacyStringSubtypeInfo(ItemStack s,UidContext context){return getSubtypeData(s,context).toString();}};for(var item:java.util.List.of(OilBotanyContent.FLOWER_ITEM.get(),OilBotanyContent.TALL_ITEM.get()))e.registerSubtypeInterpreter(item,interpreter);}
}
